// Webpack incremental build
module.exports = {
  cache: {
    type: 'filesystem',
    cacheDirectory: path.resolve(__dirname, '.webpack_cache')
  },

  // Only build changed files
  watch: true,

  // Parallel processing
  parallelism: require('os').cpus().length - 1
};

// Git-based incremental builds
const git = require('simple-git')(process.cwd());

async function getChangedFiles() {
  const changedFiles = await git.diff(['--name-only', 'HEAD~1', 'HEAD']);
  return changedFiles;
}

async function buildOnlyChanged() {
  const changedFiles = await getChangedFiles();

  // Only process changed files
  const entryPoints = changedFiles
    .filter(file => file.endsWith('.js'))
    .map(file => file.replace('.js', ''));

  // Build only changed entry points
  entryPoints.forEach(entry => {
    webpack(configs[entry]);
  });
}

const { BundleAnalyzerPlugin } = require('webpack-bundle-analyzer');
const { StatsWriterPlugin } = require('webpack-stats-plugin');

module.exports = {
  plugins: [
    // Bundle analysis report
    new BundleAnalyzerPlugin({
      analyzerMode: 'static',
      reportFilename: 'reports/bundle-report.html'
    }),

    // Build statistics
    new StatsWriterPlugin({
      filename: 'reports/build-stats.json',
      statsOptions: {
        source: false,
        modules: false,
        chunks: false
      }
    }),

    // Source maps for production debugging
    new webpack.SourceMapDevToolPlugin({
      filename: '[file].map'
    })
  ]
};

// Generate build metadata
const buildInfo = {
  timestamp: new Date().toISOString(),
  commit: process.env.GITHUB_SHA,
  branch: process.env.GITHUB_REF,
  buildNumber: process.env.GITHUB_RUN_NUMBER,
  buildUrl: process.env.GITHUB_SERVER_URL
};

fs.writeFileSync('build-info.json', JSON.stringify(buildInfo, null, 2));

// package.json scripts
"scripts": {
  "lint": "eslint src/**/*.{js,jsx,ts,tsx}",
  "typecheck": "tsc --noEmit",
  "test": "jest --coverage",
  "build": "webpack --mode production",
  "ci": "npm run lint && npm run typecheck && npm test && npm run build",

  "build:check": "npm run build && npm run analyze:bundle",
  "analyze:bundle": "webpack-bundle-analyzer dist/static/js/*.js --mode static --no-open"
}

// size-limit for performance budgets
"size-limit": [
  {
    "path": "dist/*.js",
    "limit": "200 KB"
  },
  {
    "path": "dist/*.css",
    "limit": "50 KB"
  }
]

// Build metrics collection
const buildMetrics = {
  startTime: Date.now(),
  stages: {},
  cacheHits: 0,
  cacheMisses: 0
};

function recordStage(stageName, duration) {
  buildMetrics.stages[stageName] = duration;
}

function recordCacheHit() {
  buildMetrics.cacheHits++;
}

function recordCacheMiss() {
  buildMetrics.cacheMisses++;
}

// After build completes
buildMetrics.totalTime = Date.now() - buildMetrics.startTime;
buildMetrics.cacheHitRate = buildMetrics.cacheHits / 
  (buildMetrics.cacheHits + buildMetrics.cacheMisses);

// Send to monitoring
console.log('Build Metrics:', JSON.stringify(buildMetrics, null, 2));
